mapper.update:
UPDATE export_job
SET status       = 'done',
    completed_at = NOW(),
    last_error   = NULL
WHERE checkpoint_date = #{checkpointDate}
  AND corporate_number = #{corporateNumber}
  AND claimed_by = #{workerId}

UPDATE export_job
SET status     = 'failed',
    last_error = #{error}
WHERE checkpoint_date = #{checkpointDate}
  AND corporate_number = #{corporateNumber}
  AND claimed_by = #{workerId}
